def division_of_first_even_odd(lst):
    """
    Returns the division of the first even number by the first odd number in the list.
    If either does not exist, returns None.
    """
    first_even = None
    first_odd = None
    for num in lst:
        if num % 2 == 0 and first_even is None:
            first_even = num
        elif num % 2 != 0 and first_odd is None:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    if first_even is None or first_odd is None:
        return None
    return first_even / first_odd
```

